abhinav_1_2 = {
    'hi': '।।7.1--7.2।। श्री अभिनवगुप्त कहते हैं: मुझ परमेश्वर में अनन्य अनुरागपूर्वक मन को लगाकर, मुझको ही परम आश्रय मानकर योगभ्यास करते हुए जिस प्रकार तुम मुझ सर्वात्मा को असंशय जानोगे, वह ज्ञान और अनुभव-ज्ञान (विज्ञान) मैं तुमसे सम्पूर्णता से कहूँगा, जिसे जानकर संसार में और कुछ जानने योग्य नहीं बचता।',
    'en': '7.1--7.2 Sri Abhinavagupta states: With mind intently attached to Me, taking Me as your sole refuge and practicing Yoga, hear how you shall know Me, the Supreme Lord, completely without doubt. I shall impart to you in full this wisdom combined with realization, knowing which nothing further remains to be known in this world.',
    'be': '৭.১--৭.২ শ্রী অভিনবগুপ্ত বলেছেন: আমা পরমেশ্বরে অনন্য অনুরাগপূর্ব ক মনকে লাগিয়ে, আমাকেই পরম আশ্রয় মেনে যোগাভ্যাস করতে করতে যে ভাবে তুমি আমা সর্বাত্মাকে অসংশয় জানবে, সেই জ্ঞান ও অভিজ্ঞতা-জ্ঞান (বিজ্ঞান) আমি তোমার থেকে সম্পূর্ণতায় বলব, যা জেনে সংসারে আর কিছু জানার যোগ্য থাকে না।',
    'ka': '೭.೧--೭.೨ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಪರಮೇಶ್ವರನಾದ ನನ್ನಲ್ಲಿ ಅನನ್ಯ ಅನುರಾಗಪೂರ್ವಕವಾಗಿ ಮನಸ್ಸನ್ನಿಟ್ಟು, ನನ್ನನ್ನೇ ಪರಮ ಆಶ್ರಯವೆಂದು ಭಾವಿಸಿ ಯೋಗಾಭ್ಯಾಸ ಮಾಡುತ್ತಾ ಯಾವ ರೀತಿ ನೀನು ಸರ್ವಾತ್ಮನಾದ ನನ್ನನ್ನು ಸಂಶಯವಿಲ್ಲದೆ ಅರಿಯುವೆಯೋ, ಆ ಜ್ಞಾನವನ್ನೂ ಅನುಭವಜ್ಞಾನವನ್ನೂ (ವಿಜ್ಞಾನ) ನಾನು ನಿನಗೆ ಸಂಪೂರ್ಣವಾಗಿ ತಿಳಿಸುವೆನು, ಯಾವುದನ್ನು ತಿಳಿದ ನಂತರ ಈ ಪ್ರಪಂಚದಲ್ಲಿ ಮತ್ತೇನೂ ತಿಳಿಯಬೇಕಾದದ್ದು ಉಳಿಯುವುದಿಲ್ಲವೋ'
}

abhinav_4_5 = {
    'hi': '।।7.4--7.5।। श्री अभिनवगुप्त कहते हैं: भूमि, जल, अग्नि, वायु, आकाश, मन, बुद्धि और अहंकार—यह मेरी आठ प्रकार की अविद्या-रूपा अपरा प्रकृति है। हे महाबाहो ! इस अचेतन प्रकृति से भिन्न मेरी जीव-भूता चैतन्य-रूपा परा प्रकृति को जानो, जिससे यह सम्पूर्ण जगत् धारण किया जाता है।',
    'en': '7.4--7.5 Sri Abhinavagupta states: Earth, water, fire, air, ether, mind, intellect, and egoism—this is My eightfold lower unmanifest nature (Apara Prakriti). O mighty-armed, know My other higher consciousness-nature (Para Prakriti), the life-force, by which this entire universe is sustained.',
    'be': '৭.৪--৭.৫ শ্রী অভিনবগুপ্ত বলেছেন: ভূমি, জল, অগ্নি, বায়ূ, আকাশ, মন, বুদ্ধি ও অহংকার—এটা আমার আট প্রকারের অবিদ্যা-রূপা অপরা প্রকৃতি। হে মহাবাহো! এই অচেতন প্রকৃতি থেকে ভিন্ন আমার জীব-ভূতা চৈতন্য-রূপা পরা প্রকৃতিকে জানো, যা থেকে এই সম্পূর্ণ জগৎ ধারণ করা হয়।',
    'ka': '೭.೪--೭.೫ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಭೂಮಿ, ಜಲ, ಅಗ್ನಿ, ವಾಯು, ಆಕಾಶ, ಮನಸ್ಸು, ಬುದ್ಧಿ ಹಾಗೂ ಅಹಂಕಾರ—ಇದು ನನ್ನ ಎಂಟು ಪ್ರಕಾರದ ಅವಿದ್ಯಾರೂಪವಾದ ಅಪರಾ ಪ್ರಕೃತಿಯಾಗಿದೆ. ಹೇ ಮಹಾಬಾಹೋ! ಈ ಅಚೇತನ ಪ್ರಕೃತಿಗಿಂತಲೂ ಭಿನ್ನವಾದ ನನ್ನ ಜೀವಭೂತವಾದ ಚೈತನ್ಯರೂಪದ ಪರಾ ಪ್ರಕೃತಿಯನ್ನು ತಿಳಿಯಿ, ಯಾವುದರಿಂದ ಈ ಸಮಸ್ತ ಜಗತ್ತು ಧರಿಸಲ್ಪಟ್ಟಿದೆಯೋ'
}

